# builds verify20.py from verify19.py: re-anchors the old checks to the round 20 text (anchored patches; every old string asserted) and adds the round 20 checks and plants
s = open('verify19.py', encoding='utf-8').read().replace('scratch19', 'scratch20')
def R(a, b, n=None):
    global s
    c = s.count(a)
    assert c >= 1 and (n is None or c == n), (c, n, a[:90])
    s = s.replace(a, b)
# files of round 20
R("'r19-OWNER-DAY-SHEET.md'", "'r20-OWNER-DAY-SHEET.md'", 1); R("'r19-OWNER-APPENDIX-K.md'", "'r20-OWNER-APPENDIX-K.md'", 1)
R("'r19-pins.txt'", "'r20-pins.txt'", 1); R("F('r19 pin file r19-pins.txt is missing')", "F('r20 pin file r20-pins.txt is missing')", 1)
R("'r19-CHANGES.md'", "'r20-CHANGES.md'", 1); R("F('r19 changes file r19-CHANGES.md is missing')", "F('r20 changes file r20-CHANGES.md is missing')", 1)
R("_rnd.seed(19)", "_rnd.seed(20)", 1)
# ND: 20 items
R("if nums != list(range(1, 18)): F('ND numbers')", "if nums != list(range(1, 21)): F('ND numbers')", 1)
R("if 'items 1 to 17' not in ndsec: F('ND header count')", "if 'items 1 to 20' not in ndsec: F('ND header count')", 1)
R("if any(x < 1 or x > 17 for x in nn): F('ND number out of range')", "if any(x < 1 or x > 20 for x in nn): F('ND number out of range')", 1)
# five alarms
R("'Set four alarms' not in t12n", "'Set five alarms' not in t12n", 1)
R("neg('r15short', 'In short: set four alarms', 'Set four alarms', 'r15 E-48 intro lacks')", "neg('r15short', 'In short: set five alarms', 'Set five alarms', 'r15 E-48 intro lacks')", 1)
R("neg('r16code', 'In short: set four alarms', 'In short (E-12): set four alarms', 'r16 internal code in owner text')", "neg('r16code', 'In short: set five alarms', 'In short (E-12): set five alarms', 'r16 internal code in owner text')", 1)
R("if _AP.count('Alarm 4: Tue 24 Nov 2026 06:00 UTC = 11:30 IST') != 1: F('r19 alarm 4 in the sheet')", "if _AP.count('Alarm 4: Mon 23 Nov 2026 18:24 UTC = 23:54 IST') != 1 or _AP.count('Alarm 5: Tue 24 Nov 2026 00:30 UTC = 06:00 IST') != 1: F('r20 alarm 4 or alarm 5 in the sheet')", 1)
R("'Alarm 4: Tue 24 Nov 2026 06:00 UTC = 11:30 IST')", "'Alarm 4: Mon 23 Nov 2026 18:24 UTC = 23:54 IST', 'Alarm 5: Tue 24 Nov 2026 00:30 UTC = 06:00 IST')", 1)
R("'## Your four alarms'", "'## Your five alarms'", 1)
# card step 1 (before 18:19), the clock rule, the shred rule check 2, the step 21 heading
R("'1. You: make sure that you have confirmed'", "'1. You: before 18:19 UTC = 23:49 IST on the last day (key step D.5), make sure that you have confirmed'")
R("'the assistant has no timer: it reads the time shown on your last message'", "'the assistant has no timer: on that day start every message that you write with the time in UTC'", 1)
R("'It contains no `..`, no space, no quote sign'", "'It contains no `..`, no space, no line break, no quote sign'", 1)
R("('no `..`, no space, no quote sign', 'no `..`, no quote sign')", "('no `..`, no space, no line break, no quote sign', 'no `..`, no line break, no quote sign')", 1)
R("### Step 21. Watch the cut by Mon 23 Nov 2026 18:19 UTC = 23:49 IST", "### Step 21. Watch the cut by Mon 23 Nov 2026 17:49 UTC = 23:19 IST (alarm 1)")
R("### Step 21. Watch the cut by Mon 23 Nov 2026 18:21 UTC = 23:51 IST", "### Step 21. Watch the cut by Mon 23 Nov 2026 17:51 UTC = 23:21 IST (alarm 1)", 1)
# day sheet: five alarms; size limit is the order's number (6,300 words)
R("if len(_DAY.split()) < 2500 or len(_DAY.split()) > 4800: F('r19 day sheet word count %d' % len(_DAY.split()))", "if len(_DAY.split()) < 2500 or len(_DAY.split()) > 6300: F('r20 day sheet word count %d (the limit of ORDERS.md line 227 is 6300)' % len(_DAY.split()))", 1)
# _CANON19: round 20 phrases
R("    'to be confirmed by the studio lead before you rely on it': (11, 5, 1),\n", "    'this date is a proposal: it stands if the assistant names no other date before your first take': (CANON_TBC),\n", 1)
R("    'if the secret key for the model is still not revoked, revoke it now': (2, 1, 0),\n", "    'still not revoked: revoke the secret key for the model now': (CANON_A4),\n    'the secret key for the model must be revoked now': (CANON_A5),\n", 1)
R("    'Which one counts as used by your own n8n': (1, 1, 0),\n", "    'Rotate first, then delete': (CANON_ROT),\n", 1)
R("    'alarm 1, alarm 3 and the last time to revoke': (2, 1, 0),\n", "    'alarm 1, alarm 3, alarm 4, alarm 5, an emergency (key step D.3) and the last time to revoke': (CANON_EXC),\n", 1)
R("    'your list says that your own n8n does not use it': (1, 1, 0),\n", "    'and that carries `take-only`': (CANON_TO),\n    'The key has no date and no later date': (CANON_NODATE),\n    'The real latest time to confirm in route B is when alarm 1 rings, 17:49 UTC = 23:19 IST': (CANON_B2),\n", 1)
R("('your list says that your own n8n does not use it', 'your list says nothing about your own n8n'),", "('and that carries `take-only`', 'and that carries `used`'),\n          ('The key has no date and no later date', 'The key has a later date'),\n          ('The real latest time to confirm in route B is when alarm 1 rings, 17:49 UTC = 23:19 IST', 'The real latest time to confirm in route B is 18:19 UTC = 23:49 IST'),\n          ('and so does item 5 for the login that it concerns', 'and item 5 still has to pass'),", 1)
R("    '`yes, no more takes`': (31, 11, 3),", "    '`yes, no more takes`': (CANON_YNT),", 1)
R("    '`key gone, no more decisions`': (25, 14, 1),", "    '`key gone, no more decisions`': (CANON_KG),", 1)
R("    '`key revoked`': (17, 10, 0),", "    '`key revoked`': (CANON_KR),", 1)
R("    '18:19 UTC = 23:49 IST': (38, 16, 8),", "    '18:19 UTC = 23:49 IST': (CANON_1819),", 1)
R("    '18:29 UTC = 23:59 IST': (30, 10, 4),", "    '18:29 UTC = 23:59 IST': (CANON_1829),", 1)
R("    '17:49 UTC = 23:19 IST': (2, 1, 0),", "    '17:49 UTC = 23:19 IST': (CANON_1749),", 1)
R("    '06:00 UTC = 11:30 IST': (2, 1, 0),", "    '00:30 UTC = 06:00 IST': (CANON_0030),\n    '18:24 UTC = 23:54 IST': (CANON_1824),\n    '06:30 UTC = 12:00 IST': (CANON_0630),", 1)
R("    'Tue 24 Nov 2026 18:29 UTC = 23:59 IST': (10, 4, 1),", "    'Tue 24 Nov 2026 18:29 UTC = 23:59 IST': (CANON_TUE),", 1)
R("    _TW: (6, 2, 1),", "    _TW: (CANON_TW),", 1)
R("    _WARN3: (3, 2, 0),", "    _WARN3: (CANON_W3),", 1)
R("    'the last 10 minutes': (5, 4, 2),", "    'the last 10 minutes': (CANON_L10),", 1)
canon = open('r20-canon.py', encoding='utf-8').read()
a = s.index('_CANON19 = {')
s = s[:a] + canon + '\n' + s[a:]
R("    'In route A the live key exists for hours, in route B for up to five days': (2, 0, 1),","    'In route A the live key exists for hours, in route B for up to five days': (2, 1, 1),")
R("    'No default pick: the assistant does not recommend a route': (1, 0, 0),","    'No default pick: the assistant does not recommend a route': (1, 1, 0),")
R("    'no reply counts as `another take`': (2, 0, 0),","    'no reply counts as `another take`': (2, 1, 0),")
R("    '`key revoked` is never a confirmation': (1, 0, 0),","    '`key revoked` is never a confirmation': (1, 1, 0),")
R("    'It never confirms anything, at any time': (1, 0, 0),","    'It never confirms anything, at any time': (1, 1, 0),")
R("    'asks you to type the words yourself in a new message': (1, 0, 0),","    'asks you to type the words yourself in a new message': (1, 1, 0),")
R("    'A confirmation is exactly one of two messages': (2, 0, 0),","    'A confirmation is exactly one of two messages': (2, 1, 0),")
R("    '`cut accepted`': (16, 2, 1),","    '`cut accepted`': (16, 8, 1),")
R("    '`route A`': (4, 1, 0),","    '`route A`': (4, 2, 0),")
R("    '`route B`': (4, 1, 0),","    '`route B`': (4, 2, 0),")
_sec20 = open('r20-section.py', encoding='utf-8').read()
_m20 = "# ================= negative controls (each check must fail on a planted defect) ================="
assert s.count(_m20) == 1
s = s.replace(_m20, _sec20 + '\n' + _m20)
open('verify20.py', 'w', encoding='utf-8').write(s)
print('verify20.py written', len(s.split('\n')), 'lines')
